<template>
  <main class="is-flex is-flex-direction-column is-justify-content-space-between is-full-height has-background-shade-4 is-relative">
    <div class="toolbar has-border-bottom-shade-3">
      <router-link v-if="!$xmpp.isAnonymous" :to="{ name: 'home' }" class="button is-primary-ghost has-no-border is-shadowless" :class="{ 'is-hidden-tablet': jid }" title="Back to contacts"><i class="fa-solid fa-circle-chevron-left" aria-hidden="true" /></router-link>
      <router-link v-else :to="{ name: 'guestRooms', state: { nick: userNick } }" class="button is-primary-ghost has-no-border is-shadowless" title="Leave this room and go back to rooms list"><i class="fa-solid fa-circle-chevron-left" aria-hidden="true" /></router-link>
      <i class="fa-solid fa-lg fa-pen-to-square" :class="chatStateClass" aria-hidden="true" />
      <span class="is-flex is-align-items-center" style="min-width: 0;">
        <room-occupants v-if="isRoom" />
        <bookmark-button v-if="isRoom && !$xmpp.isAnonymous" />
        <room-configuration-button v-if="isRoom && !$xmpp.isAnonymous" />
        <invite-guest-button v-if="hasGuestInviteLink" />
        <retrieve-history-button />
        <presence-controller v-if="$xmpp.isAnonymous" :is-navbar-item="false" :is-right="true" class="px-2 mx-2" />
      </span>
    </div>
    <div id="messages-container" class="messages-container">
      <room-subject v-if="isRoom" />
      <TransitionGroup name="messages-list">
        <message-container v-for="message in messagesWithJid" :key="message.id" :message="message" />
      </TransitionGroup>
    </div>
    <sendbox />
  </main>
</template>

<script>
import { mapState } from 'pinia'
import { useStore } from '@/store'
import BookmarkButton from '../Registered/BookmarkButton.vue'
import InviteGuestButton from './InviteGuestButton.vue'
import MessageContainer from './MessageContainer.vue'
import Modal from './Modal.vue'
import PresenceController from './PresenceController.vue'
import RoomConfigurationButton from '../Registered/RoomConfigurationButton.vue'
import RetrieveHistoryButton from './RetrieveHistoryButton.vue'
import RoomOccupants from './RoomOccupants.vue'
import RoomSubject from './RoomSubject.vue'
import Sendbox from './Sendbox.vue'

export default {
  name: 'Chat',
  components: {
    InviteGuestButton,
    BookmarkButton,
    MessageContainer,
    RoomConfigurationButton,
    RetrieveHistoryButton,
    RoomOccupants,
    RoomSubject,
    Sendbox,
    PresenceController,
  },
  provide() {
    return {
      jid: this.jid,
      isRoom: this.isRoom,
    }
  },
  beforeRouteEnter (to, from, next) {
    next(vm => {
      vm.previousRoute = from
    })
  },
  props: {
    jid: {
      type: String,
      default: null,
    },
    isRoom: {
      type: Boolean,
      default: false,
    },
  },
  data () {
    return {
      previousRoute: null,
    }
  },
  computed: {
    userJid () {
      return this.$xmpp.fullJid
    },
    userNick () {
      return this.$xmpp.nick
    },
    messagesWithJid () {
      return this.messages.filter((message) => (message.from.bare === this.jid || message.to.bare === this.jid))
    },
    chatStateClass () {
      switch (this.$store.getChatState(this.isRoom, this.jid)) {
        case 'composing':
          return 'has-text-grey-light'
        case 'paused':
          return 'has-text-shade-3'
        default:
          return 'has-text-shade-4'
      }
    },
    ...mapState(useStore, [
      'activeChat',
      'messages',
      'isSendingInactiveChatStates',
    ]),
    hasGuestInviteLink () {
      return window.config.hasGuestAccess && this.isRoom
    },
  },
  // watch route param to force component update
  watch: {
    jid: 'handleRoute',
    messagesWithJid: 'scrollToLastMessage',
  },
  mounted () {
    // handle route prop
    this.handleRoute()
  },
  async beforeUnmount () {
    if (!this.userJid) {
      // $xmpp is not loaded
      return
    }
    if (!this.isSendingInactiveChatStates) {
      // the user has not opted in
      return
    }
    // notify leaving discussion
    try {
      await this.$xmpp.sendChatState(this.jid, this.isRoom, 'inactive')
    } catch (error) {
      console.warn(error.message)
    }
  },
  methods: {
    // handle route on mount (commit active chat, reset first message, join room if not already)
    async handleRoute () {
      if (!this.userJid) {
        // $xmpp is not loaded
        return
      }
      this.$store.setActiveChat({
        type: this.isRoom ? 'groupchat' : 'chat',
        activeChat: this.jid,
      })
      if (this.isRoom && !this.$store.isJoined(this.jid)) {
        // user was not in this room, he have to join before
        let room = this.$store.getRoom(this.jid)
        const options = { }
        if (!room || !room.jid) {
          // room is not known, request more info
          room = await this.$xmpp.getRoom(this.jid)
          if (!room.jid) {
            // handle room error
            await new Promise((resolve) =>
              this.$oruga.modal.open({
                component: Modal,
                trapFocus: true,
                props: {
                  title: 'Error',
                  message: room.message || 'Unable to join room',
                  type: 'is-danger',
                },
                onClose: () => resolve(false),
              }),
            )
            return this.abortChat()
          }
        }
        if (room.jid && room.isPasswordProtected) {
          // room is protected, asking password
          const result = await new Promise((resolve) =>
            this.$oruga.modal.open({
              rootClass: 'dialog',
              trapFocus: true,
              component: Modal,
              onCancel: () => resolve(false),
              props: {
                title: 'Room protected',
                message: '<span class="icon mr-2"><i class="fa-solid fa-key" /></i></span><span>Please enter password</span>',
                prompt: {
                  placeholder: 'Password',
                  type: 'password',
                  value: room.password || '',
                },
                onPromptAnswered: resolve,
              },
            }),
          )
          options.muc = {
            password: result,
          }
          if (result === false) {
            return this.abortChat()
          }
        }
        const result = await this.$xmpp.joinRoom(this.jid, null, options, room)
        if (!result.isSuccess) {
          this.$oruga.modal.open({
            component: Modal,
            trapFocus: true,
            props: {
              title: 'Error',
              message: result.message || 'Unable to join room',
              type: 'is-danger',
            },
          })
          return this.abortChat()
        }
      }
      if (!this.isRoom && this.messagesWithJid.length === 0) {
        // request history
        try {
          await this.$xmpp.searchHistory(this.activeChat, undefined)
        } catch (error) {
          console.warn('History was not loaded', error.message)
        }
      }
      this.scrollToLastMessage()
    },
    abortChat () {
      // choose valid path for navigation
      if (this.previousRoute && this.previousRoute.query.redirect === this.$route.fullPath) {
        if (this.$xmpp.isAnonymous) {
          return this.$router.push({ name: 'guest' })
        }
        return this.$router.push({ name: 'home' })
      }
      if (history.state && history.state.back) {
        return this.$router.replace({ path: history.state.back })
      }
      return this.$router.back()
    },
    // scroll to last message (called when messages changes)
    scrollToLastMessage () {
      this.$nextTick(() => {
        const messagesContainer = document.getElementById('messages-container')
        if (messagesContainer) {
          messagesContainer.scrollTop = messagesContainer.scrollHeight + 5000
        }
      })
    },
  },
}
</script>
